test_suite:
test('subscriber receives published data', () => {
  const bus = new PubSub();
  const log = [];
  bus.subscribe('news', d => log.push(d));
  bus.publish('news', 'headline');
  expect(log).toEqual(['headline']);
});

test('wildcard subscriber receives all publications', () => {
  const bus = new PubSub();
  const log = [];
  bus.subscribe('*', d => log.push(d));
  bus.publish('a', 1);
  bus.publish('b', 2);
  expect(log).toEqual([1, 2]);
});

test('unsubscribe stops delivery', () => {
  const bus = new PubSub();
  const log = [];
  const fn = d => log.push(d);
  bus.subscribe('x', fn);
  bus.publish('x', 1);
  bus.unsubscribe('x', fn);
  bus.publish('x', 2);
  expect(log).toEqual([1]);
});

test('multiple subscribers on same topic each receive data', () => {
  const bus = new PubSub();
  const a = [], b = [];
  bus.subscribe('t', d => a.push(d));
  bus.subscribe('t', d => b.push(d));
  bus.publish('t', 'hello');
  expect(a).toEqual(['hello']);
  expect(b).toEqual(['hello']);
});

