test('publish does not call listeners of other topics', () => {
  const bus = new PubSub();
  const log = [];
  bus.subscribe('alpha', d => log.push('alpha:' + d));
  bus.subscribe('beta', d => log.push('beta:' + d));
  bus.publish('alpha', 'x');
  expect(log).toEqual(['alpha:x']);
});

solution:
export class PubSub {
  constructor() {
    this._listeners = new Map();
  }

  subscribe(topic, fn) {
    if (!this._listeners.has(topic)) this._listeners.set(topic, new Set());
    this._listeners.get(topic).add(fn);
  }

  publish(topic, data) {
    if (this._listeners.has(topic)) {
      this._listeners.get(topic).forEach(fn => fn(data));
    }
    if (topic !== '*' && this._listeners.has('*')) {
      this._listeners.get('*').forEach(fn => fn(data));
    }
  }

  unsubscribe(topic, fn) {
    if (this._listeners.has(topic)) {
      this._listeners.get(topic).delete(fn);
    }
  }
}
